fun describe(code: Int) = when (code) {
    200, 201 -> "ok"
    in 400..499 -> "client"
    !in 0..599 -> "invalid"
    else -> "other"
}

fun main() {
    println(listOf(201, 404, 302, 700).joinToString { describe(it) })
}

